            has_signal = bool(_MATH_GLYPH_RE.search(body) or "\\" in body or "=" in body)
            if len(run) >= 2 and has_signal and len(body) >= 4:
                head = run[0]
                head.en = body
                head.payload["merged_from"] = [x.id for x in run[1:]]
