.ptable td { padding: 13px 12px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.ptable tbody tr { cursor: pointer; transition: background .12s ease; }
.ptable tbody tr:hover { background: var(--fg-soft); }
.ptable .t-title { font-weight: 545; font-size: 13.5px; line-height: 1.35; color: var(--fg); }
/* 「编辑」按钮（⑲ 手动改元数据的入口）：跟随行 hover 显现，平时不抢占标题的注意力。
   必须 stopPropagation —— 整行可点是"进阅读器"，编辑是另一件事。 */
.ptable .t-edit {
  margin-left: 8px; font-size: 11px; padding: 1px 7px; border-radius: 999px;
  border: 1px solid var(--border); background: transparent; color: var(--muted);
  cursor: pointer; opacity: 0; transition: opacity .12s ease;
}
.ptable tbody tr:hover .t-edit, .ptable .t-edit:focus-visible { opacity: 1; }
.ptable .t-edit:hover { color: var(--accent); border-color: var(--accent); }
/* 删除是破坏性动作，hover 时给 danger 色 —— 与「编辑」区分开，
   免得两个一模一样的胶囊按钮并排、点错代价却完全不同。 */
.ptable .t-del:hover { color: var(--danger); border-color: var(--danger); }
.ptable .t-edit:disabled { opacity: .4; cursor: not-allowed; }
/* 触屏没有 hover，永远看得见（否则该入口等于不存在） */
@media (hover: none) { .ptable .t-edit { opacity: 1; } }
.ptable .t-sub { font-family: var(--font-mono); font-size: 11px; color: var(--muted); margin-top: 3px; }
.ptable .t-year { font-family: var(--font-mono); font-size: 12.5px; color: var(--fg); }
.ptable .t-venue { font-size: 12px; color: var(--muted); }
.ptable .t-tags { display: flex; gap: 4px; flex-wrap: wrap; max-width: 190px; }
.ptable .num-col { text-align: right; font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.table-foot { display: flex; align-items: center; justify-content: space-between; padding: 14px 2px 0; }

