def reset_code(body: EmailIn, conn: sqlite3.Connection = Depends(get_conn),
               settings: Settings = Depends(get_settings)) -> dict[str, Any]:
    """忘记密码用验证码。

    ⚠️ **不泄露邮箱是否已注册**：未注册时也走同一条成功路径（同样耗掉一次冷却），
